$content = Get-Content "app/src/main/java/com/attendance/app/teacher/ui/TeacherHomeScreen.kt" -Raw
$content = $content -replace "(?s)@Composable\s*fun TeacherBottomBar.*", "@Composable`nfun TeacherBottomBar(navController: NavController, selectedIndex: Int) {`n    NavigationBar {`n        NavigationBarItem(icon = { Icon(Icons.Default.Home, `"Home`") }, label = { Text(`"Home`") }, selected = selectedIndex == 0, onClick = { navController.navigate(Screen.TeacherHome) { launchSingleTop = true } })`n        NavigationBarItem(icon = { Icon(Icons.Default.Class, `"Classes`") }, label = { Text(`"Classes`") }, selected = selectedIndex == 1, onClick = { navController.navigate(Screen.TeacherClasses) { launchSingleTop = true } })`n        NavigationBarItem(icon = { Icon(Icons.Default.History, `"History`") }, label = { Text(`"History`") }, selected = selectedIndex == 2, onClick = { navController.navigate(Screen.TeacherHistory) { launchSingleTop = true } })`n        NavigationBarItem(icon = { Icon(Icons.Default.Person, `"Profile`") }, label = { Text(`"Profile`") }, selected = selectedIndex == 3, onClick = { navController.navigate(Screen.TeacherProfile) { launchSingleTop = true } })`n    }`n}"
Set-Content "app/src/main/java/com/attendance/app/teacher/ui/TeacherHomeScreen.kt" $content
